-.site-title {
-  font-weight: 700;
-  letter-spacing: -0.04em;
+/*
+ * Starlight's own `Search.astro` gives its trigger button a bordered,
+ * filled pill at desktop widths (`@layer starlight.core`) — the
+ * gold-standard topbar has no such box, just the icon, placeholder text,
+ * and a light `⌘K` badge inline against the topbar itself. Unlayered so
+ * it wins unconditionally over Starlight's own media-query-gated rule.
+ */
+.search button[data-open-modal] {
+  border: 0;
+  border-radius: 0;
+  background-color: transparent;
+  max-width: none;
+  padding-inline: 0;
+  /*
+   * Starlight's own desktop-width rule (>=50rem, which every topbar
+   * layout here qualifies for) colors this button with --sl-color-gray-2
+   * — mapped to --bg-2, a background tint, not a text color, so the
+   * placeholder text and icon were nearly invisible. --sl-color-gray-2
+   * is used far too widely elsewhere (hover fills, code-block chrome) to
+   * safely remap wholesale, so fix it here, scoped to just this button.
+   */
+  color: var(--fg-muted);
+}
+.search button[data-open-modal]:hover {
+  border-color: transparent;
+  color: var(--fg-secondary);
 }
